def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {"up": 0, "down": 0}

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            rows = sorted({y for y, x in cells})
            if len(cells) != 4 or len(rows) != 2:
                continue
            top = [x for y, x in cells if y == rows[0]]
            bottom = [x for y, x in cells if y == rows[1]]
            if len(top) == 1 and len(bottom) == 3:
                counts["up"] += 1
            elif len(top) == 3 and len(bottom) == 1:
                counts["down"] += 1

    out = [[0] * 6 for _ in range(3)]
    slots = [(0, 0), (0, 2), (2, 0), (2, 2)]
    for kind, color, offset in (("up", 3, 0), ("down", 1, 3)):
        for i in range(min(counts[kind], len(slots))):
            y, x = slots[i]
            out[y][x + offset] = color
    return out
